insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-pe-276","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The p-block is the only block that contains metals, metalloids and non-metals in the","options":["s-block groups","same set of groups","f-block rows","first period alone"],"answer_index":1,"explanation":"Group 14, for example, runs from non-metal C through metalloid Si/Ge to metals Sn and Pb.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-277","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Screening of the nuclear charge is poorer by d and f electrons than by","options":["the nucleus itself","s and p electrons of the same shell","neutrons","alpha particles"],"answer_index":1,"explanation":"Penetrating s (and p) electrons cancel Z more effectively; d and f electrons leave a higher Zeff on the outside.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-278","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Neon has both a very small covalent radius and the highest first ionisation enthalpy of","options":["period 3","period 2","the alkali metals","the lanthanoids"],"answer_index":1,"explanation":"Closed-shell compactness and maximum Zeff in that row make Ne the extreme of both trends.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-279","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"From lithium to caesium, ionisation enthalpy falls while atomic radius rises, so the two trends reinforce the","options":["decrease in metallic character","increase in metallic character","rise of electronegativity","formation of noble gases"],"answer_index":1,"explanation":"A larger, more loosely held ns¹ electron makes the heavier alkali metal more metallic.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-280","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine is more electronegative than chlorine, yet chlorine has the more negative electron gain enthalpy — a pair of trends that","options":["always run in step","do not run in step","apply only to metals","forbid any F–Cl bond"],"answer_index":1,"explanation":"χ follows size/Zeff, while ΔegH of F is reduced by 2p–2p repulsion; the two properties therefore order F and Cl differently.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-281","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Na⁺ and neon are isoelectronic, but Na⁺ has the higher ionisation enthalpy because of its","options":["smaller nuclear charge","greater nuclear charge","extra 3s electron","f-block contraction"],"answer_index":1,"explanation":"Both have 10 electrons; Z(Na⁺) = 11 > Z(Ne) = 10, so the Na⁺ cloud is more tightly bound.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-282","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The first ionisation enthalpy of gallium is slightly higher than that of aluminium because the poorly shielding 3d¹⁰ electrons","options":["lower Zeff on Ga","raise Zeff on Ga","remove the 4p electron","turn Ga into an alkali metal"],"answer_index":1,"explanation":"d-block contraction increases Zeff and offsets the expected fall of IE down group 13.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-283","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Oxygen is smaller than nitrogen, which would suggest a higher IE for O, yet IE of O is lower than that of N because","options":["oxygen has a half-filled 2p³ set","the paired 2p⁴ electron of oxygen is easier to remove","nitrogen has the larger nuclear charge","oxygen lacks a 2s pair"],"answer_index":1,"explanation":"The size trend and the pairing-repulsion trend oppose each other; pairing wins, so IE(N) > IE(O).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-284","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Size decreases from Be to B, which would suggest a higher IE for B; the observed lower IE of B is due to","options":["the ease of removing the 2p electron compared with Be 2s²","a fall in nuclear charge from Be to B","boron having a closed 2p⁶ shell","beryllium being a halogen"],"answer_index":0,"explanation":"Again two trends conflict: smaller radius would raise IE, but the change of subshell (2s → 2p) lowers it.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
    chapter_id text,
    subject_id text,
    stem text,
    options jsonb,
    answer_index int,
    explanation text,
    images jsonb,
    source jsonb,
    difficulty text,
    concept_id text,
    appear_count int,
    years jsonb,
    exams jsonb,
    verified boolean
  )
on conflict (question_id) do update set
  appear_count = excluded.appear_count,
  years = excluded.years,
  exams = excluded.exams,
  verified = excluded.verified;